function currentFilters(){return{status:els.statusFilter.value,kind:els.kindFilter.value,source:els.sourceFilter.value,quality:els.qualityFilter.value}}
function filteredLocal(){const f=currentFilters();return state.summaries.filter(v=>(!f.status||(f.status==='archived'?v.archived:(!v.archived&&v.status===f.status)))&&(!f.kind||v.kind===f.kind)&&(!f.source||v.source===f.source)&&(!f.quality||(f.quality==='issues'?(v.qualityFlags||[]).length>0:(v.qualityFlags||[]).length===0)))}
function publishedRank(value){const s=String(value||'').trim();const parsed=Date.parse(s);if(Number.isFinite(parsed))return parsed;const m=s.toLowerCase().match(/(?:streamed|premiered)?\s*(\d+)\s*(second|minute|hour|day|week|month|year)s?\s+ago/);if(!m)return null;const n=Number(m[1]),unit={second:1000,minute:60000,hour:3600000,day:86400000,week:604800000,month:2629800000,year:31557600000}[m[2]];return Date.now()-n*unit}
