async function stageDiscoveryBatch(items,refreshToken){const db=await openDb();const tx=db.transaction('videos','readwrite');const os=tx.objectStore('videos');for(const item of items){const get=os.get(item.id);get.onsuccess=()=>{const old=get.result;const merged=old?{...old,...item,archived:Boolean(old.archived),transcript:old.transcript||null,status:old.status==='working'?'pending':old.status||'pending',attempts:old.attempts||[],integrityHash:old.integrityHash||'',retrievedAt:old.retrievedAt||'',_refreshToken:refreshToken,_refreshNew:false}:{...item,archived:true,status:'pending',error:'',attempts:[],transcript:null,integrityHash:'',retrievedAt:'',_refreshToken:refreshToken,_refreshNew:true};os.put(merged)}}await txP(tx);db.close()}
