function channelIdentity(c){if(c?.id)return`id:${String(c.id).toLowerCase()}`;try{const u=new URL(c?.url||'');return`url:${u.hostname.toLowerCase()}${u.pathname.replace(/\/(videos|shorts|streams)\/?$/,'').replace(/\/$/,'').toLowerCase()}`}catch{return''}}
